/**
 * Secure Express Application
 * Implements security best practices for error handling and input validation
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');
const winston = require('winston');
const cors = require('cors');

// Initialize Express app
const app = express();

// Environment configuration with defaults
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const TRUST_PROXY = process.env.TRUST_PROXY === 'true';
const CORS_ORIGIN = process.env.CORS_ORIGIN || '*'; // Set specific origin in production

// Logger configuration
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

// Trust proxy configuration (required for rate limiting behind proxies)
app.set('trust proxy', TRUST_PROXY ? 1 : false);

// Security Middleware

/**
 * Helmet middleware - Sets various HTTP headers for security
 * - X-Content-Type-Options: nosniff
 * - X-Frame-Options: DENY
 * - X-XSS-Protection: Enabled
 * - Strict-Transport-Security: HSTS
 * - Content-Security-Policy: CSP
 */
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

/**
 * CORS configuration
 * In production, specify exact allowed origins
 */
app.use(cors({
  origin: CORS_ORIGIN,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

/**
 * Rate Limiting middleware
 * Prevents brute-force and DDoS attacks
 */
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res, next, options) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(options.statusCode).json({
      success: false,
      message: 'Too many requests, please try again later.'
    });
  },
});

// Apply rate limiting to all routes
app.use('/api/', apiLimiter);

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent')?.substring(0,100)
  });
  next();
});

// Sample data store (in production, use a proper database)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

/**
 * Validation error handler helper
 * Processes express-validator results
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { errors: errors.array(), path: req.path });
    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Routes

/**
 * Health check endpoint
 * Used for monitoring and load balancer health checks
 */
app.get('/api/health', (req, res) => {
  res.status(200).json({
    success: true,
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime()
  });
});

/**
 * Get all users - Limited fields for security
 * Returns only public information
 */
app.get('/api/users', (req, res) => {
  // Return only public fields (exclude email for privacy)
  const publicUsers = users.map(user => ({
    id: user.id,
    name: user.name
  }));

  res.status(200).json({
    success: true,
    count: publicUsers.length,
    data: publicUsers
  });
});

/**
 * Get user by ID with input validation
 * Validates the ID parameter thoroughly
 */
app.get(
  '/api/users/:id',
  [
    // Input validation rules
    param('id')
      .exists().withMessage('User ID is required')
      .isInt({ min: 1 }).withMessage('User ID must be a positive integer')
      .toInt(),
    handleValidationErrors
  ],
  (req, res) => {
    const userId = req.params.id;
    const user = users.find(u => u.id === userId);

    if (!user) {
      logger.warn(`User not found: ID ${userId}`, { ip: req.ip });
      return res.status(404).json({
        success: false,
        message: 'User not found'
      });
    }

    // Return limited user information
    res.status(200).json({
      success: true,
      data: {
        id: user.id,
        name: user.name
      }
    });
  }
);

/**
 * Create new user with comprehensive validation
 */
app.post(
  '/api/users',
  apiLimiter, // Stricter rate limiting for POST
  [
    body('name')
      .exists().withMessage('Name is required')
      .trim()
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z0-9\s]+$/).withMessage('Name can only contain letters, numbers, and spaces')
      .escape(), // Prevent XSS
    body('email')
      .exists().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 254 }).withMessage('Email too long')
      .custom(value => {
        // Check for disposable email domains (example)
        const blockedDomains = ['tempmail.com', '10minutemail.com'];
        const domain = value.split('@')[1];
        if (blockedDomains.includes(domain)) {
          throw new Error('Disposable email addresses are not allowed');
        }
        return true;
      }),
    handleValidationErrors
  ],
  (req, res) => {
    const { name, email } = req.body;

    // Check for duplicate email
    const existingUser = users.find(u => u.email === email);
    if (existingUser) {
      logger.warn(`Duplicate email registration attempt: ${email}`);
      return res.status(409).json({
        success: false,
        message: 'User with this email already exists'
      });
    }

    // Create new user
    const newUser = {
      id: users.length > 0 ? Math.max(...users.map(u => u.id)) + 1 : 1,
      name,
      email
    };

    users.push(newUser);
    logger.info(`New user created: ID ${newUser.id}`);

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: {
        id: newUser.id,
        name: newUser.name
      }
    });
  }
);

// 404 Handler for undefined routes
app.use((req, res) => {
  logger.warn(`Route not found: ${req.method} ${req.url}`, { ip: req.ip });
  res.status(404).json({
    success: false,
    message: 'Resource not found'
  });
});

// Global Error Handling Middleware
// This prevents stack traces from leaking in production
app.use((err, req, res, next) => {
  const errorId = Math.random().toString(36).substring(2, 15);

  logger.error('Unhandled error', {
    errorId,
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose error details in production
  const response = {
    success: false,
    message: NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message,
  };

  // Include errorId for debugging in production
  if (NODE_ENV === 'production') {
    response.errorId = errorId;
  } else {
    // Include stack trace in development only
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// Start server
const server = app.listen(PORT, () => {
  logger.info(`Server started on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  logger.info(`${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    logger.info('Server closed. Process terminated.');
    process.exit(0);
  });
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception', { error: err.message, stack: err.stack });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', { reason, promise });
});

module.exports = app;

