// Improved app.js with basic error handling and input validation
// Focused, minimal changes for security improvement
const express = require('express');
const app = express();

// Basic JSON body parsing with size limit
app.use(express.json({ limit: '1mb' }));

// Input validation helper
const validateId = (req, res, next) => {
  if (req.params.id) {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      return res.status(400).json({ error: 'Invalid ID format' });
    }
    req.params.id = id;
  }
  next();
};

// Health endpoint with basic error handling
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint - returns limited data (no emails)
app.get('/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];
    res.json(users);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// New endpoint with ID validation example
app.get('/users/:id', validateId, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];
    const user = users.find(u => u.id === req.params.id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handler - prevents stack leaks
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(500).json({ error: 'Internal server error' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

