      maxLength: 255
    },
    password: {
      minLength: 8,
      maxLength: 128,
      // At least one uppercase, one lowercase, one number, one special char
      pattern: /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/
    }
  },

  // Helmet configuration
  helmetConfig: {
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
        connectSrc: ["'self'"],
        fontSrc: ["'self'"],
        objectSrc: ["'none'"],
        mediaSrc: ["'self'"],
        frameSrc: ["'none'"],
      },
    },
    crossOriginEmbedderPolicy: true,
    crossOriginOpenerPolicy: true,
    crossOriginResourcePolicy: { policy: "cross-origin" },
    dnsPrefetchControl: { allow: false },
    frameguard: { action: "deny" },
    hidePoweredBy: true,
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true,
    },
    ieNoOpen: true,
    noSniff: true,
    originAgentCluster: true,
    permittedCrossDomainPolicies: { permittedPolicies: "none" },
    referrerPolicy: { policy: "strict-origin-when-cross-origin" },
    xssFilter: true,
  },

  // Body parser limits
  bodyParser: {
    jsonLimit: '10kb',
    urlencodedLimit: '10kb',
    parameterLimit: 1000
  }
};

// Input validation utilities
const { body, param, query } = require('express-validator');
const securityConfig = require('../config/security');

// Sanitization helper
const sanitizeString = (value) => {
  if (typeof value !== 'string') return value;
  return value
    .trim()
    .replace(/[<>]/g, '') // Remove angle brackets
    .replace(/javascript:/gi, '') // Remove javascript: protocol
    .replace(/on\w+\s*=/gi, ''); // Remove event handlers
};

// Validation chains
const validators = {
  // User ID parameter validation
  userId: param('id')
    .notEmpty()
    .withMessage('User ID is required')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),

  // Name validation
  name: body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: securityConfig.validation.name.minLength, max: securityConfig.validation.name.maxLength })
    .withMessage(`Name must be between ${securityConfig.validation.name.minLength} and ${securityConfig.validation.name.maxLength} characters`)
    .matches(securityConfig.validation.name.pattern)
    .withMessage('Name can only contain letters, numbers, spaces, hyphens, and underscores')
    .customSanitizer(sanitizeString),

  // Email validation
  email: body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: securityConfig.validation.email.maxLength })
    .withMessage(`Email must not exceed ${securityConfig.validation.email.maxLength} characters`),

  // Password validation (for future authentication)
  password: body('password')
    .notEmpty()
    .withMessage('Password is required')
    .isLength({ min: securityConfig.validation.password.minLength, max: securityConfig.validation.password.maxLength })
    .withMessage(`Password must be between ${securityConfig.validation.password.minLength} and ${securityConfig.validation.password.maxLength} characters`)
    .matches(securityConfig.validation.password.pattern)
    .withMessage('Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character'),

  // Pagination query validation
  page: query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),

  limit: query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  // Search query validation
  search: query('q')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Search query must be between 1 and 100 characters')
    .customSanitizer(sanitizeString),
};

// Error formatter
const formatValidationErrors = (errors) => {
  return errors.array().map(error => ({
    field: error.path,
    value: error.value,
    message: error.msg,
    location: error.location
  }));
};

// Input sanitizer middleware
const sanitizeInput = (req, res, next) => {
  const sanitizeObj = (obj) => {
    for (const key in obj) {
      if (typeof obj[key] === 'string') {
        obj[key] = sanitizeString(obj[key]);
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitizeObj(obj[key]);
      }
    }
  };

  if (req.body) sanitizeObj(req.body);
  if (req.query) sanitizeObj(req.query);
  if (req.params) sanitizeObj(req.params);

  next();
};

module.exports = {
  validators,
  formatValidationErrors,
  sanitizeInput,
  sanitizeString
};

// Custom error classes and error handling utilities

class AppError extends Error {
  constructor(message, statusCode, code = null) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.code = code;
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message, details = []) {
    super(message, 400, 'VALIDATION_ERROR');
    this.details = details;
  }
}

class NotFoundError extends AppError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404, 'NOT_FOUND');
    this.resource = resource;
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized access') {
    super(message, 401, 'UNAUTHORIZED');
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Access forbidden') {
    super(message, 403, 'FORBIDDEN');
  }
}

class ConflictError extends AppError {
  constructor(message = 'Resource already exists') {
    super(message, 409, 'CONFLICT');
  }
}

class TooManyRequestsError extends AppError {
  constructor(message = 'Too many requests') {
    super(message, 429, 'TOO_MANY_REQUESTS');
  }
}

// Error handler middleware
const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    code: err.code,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method,
    ip: req.ip,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Development error response
  if (process.env.NODE_ENV === 'development') {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
      code: err.code,
      ...(err.details && { details: err.details }),
      stack: err.stack
    });
  }

  // Production error response
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
      code: err.code,
      ...(err.details && { details: err.details })
    });
  }

  // Programming or unknown errors - don't leak details
  console.error('ERROR: ', err);
  return res.status(500).json({
    status: 'error',
    message: 'Something went wrong',
    code: 'INTERNAL_ERROR'
  });
};

// Async handler wrapper to catch errors in async route handlers
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  UnauthorizedError,
  ForbiddenError,
  ConflictError,
  TooManyRequestsError,
  errorHandler,
  asyncHandler
};

// Security middleware collection
const rateLimit = require('express-rate-limit');
const securityConfig = require('../config/security');
const { TooManyRequestsError } = require('../utils/errors');

// Rate limiters
const generalLimiter = rateLimit({
  windowMs: securityConfig.rateLimiting.general.windowMs,
  max: securityConfig.rateLimiting.general.max,
  message: { error: 'Too many requests, please try again later.', code: 'TOO_MANY_REQUESTS' },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res, next, options) => {
    next(new TooManyRequestsError());
  }
});

const authLimiter = rateLimit({
  windowMs: securityConfig.rateLimiting.auth.windowMs,
  max: securityConfig.rateLimiting.auth.max,
  message: { error: 'Too many authentication attempts, please try again later.', code: 'AUTH_RATE_LIMIT' },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res, next, options) => {
    next(new TooManyRequestsError('Too many authentication attempts'));
  }
});

const sensitiveLimiter = rateLimit({
  windowMs: securityConfig.rateLimiting.sensitive.windowMs,
  max: securityConfig.rateLimiting.sensitive.max,
  message: { error: 'Too many sensitive operations, please try again later.', code: 'SENSITIVE_RATE_LIMIT' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Request sanitization
const sanitizeRequest = (req, res, next) => {
  // Prevent prototype pollution
  const removePrototypes = (obj) => {
    if (typeof obj !== 'object' || obj === null) return;

    // Remove dangerous keys
    const dangerousKeys = ['__proto__', 'constructor', 'prototype'];
    for (const key of dangerousKeys) {
      delete obj[key];
    }

    for (const key of Object.keys(obj)) {
      if (typeof obj[key] === 'object') {
        removePrototypes(obj[key]);
      }
    }
  };

  if (req.body) removePrototypes(req.body);
  if (req.query) removePrototypes(req.query);
  if (req.params) removePrototypes(req.params);

  // XSS prevention
  const sanitizeString = (str) => {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;')
      .replace(/\//g, '&#x2F;');
  };

  const sanitizeObj = (obj) => {
    for (const key in obj) {
      if (typeof obj[key] === 'string') {
        obj[key] = sanitizeString(obj[key].trim());
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitizeObj(obj[key]);
      }
    }
  };

  if (req.body) sanitizeObj(req.body);

  next();
};

// Security headers
const securityHeaders = (req, res, next) => {
  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Restrict referrer information
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Control DNS prefetch
  res.setHeader('X-DNS-Prefetch-Control', 'off');

  // Feature policy / permissions policy
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');

  next();
};

// Request size validation
const validateRequestSize = (req, res, next) => {
  const contentLength = parseInt(req.headers['content-length']);
  const maxSize = 10 * 1024; // 10KB

  if (contentLength && contentLength > maxSize) {
    return res.status(413).json({
      error: 'Request entity too large',
      code: 'PAYLOAD_TOO_LARGE'
    });
  }

  next();
};

// Block suspicious patterns
const blockSuspiciousPatterns = (req, res, next) => {
  const suspiciousPatterns = [
    /(\b(union|select|insert|update|delete|drop|create|alter|exec)\b.*\b(from|into|table|database)\b)/i, // SQL injection
    /(<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>)/i, // XSS
    /(\b(eval|exec|system|passthru|shell_exec)\s*\()/i, // Command injection
    /(\.\.+)\//, // Path traversal
    /%00/, // Null byte injection
  ];

  const checkPattern = (value) => {
    if (typeof value !== 'string') return false;
    return suspiciousPatterns.some(pattern => pattern.test(value));
  };

  const scanObject = (obj) => {
    for (const key in obj) {
      if (typeof obj[key] === 'string' && checkPattern(obj[key])) {
        return true;
      }
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        if (scanObject(obj[key])) return true;
      }
    }
    return false;
  };

  if (req.body && scanObject(req.body)) {
    return res.status(400).json({
      error: 'Suspicious content detected',
      code: 'SUSPICIOUS_CONTENT'
    });
  }

  if (req.query && scanObject(req.query)) {
    return res.status(400).json({
      error: 'Suspicious content detected',
      code: 'SUSPICIOUS_CONTENT'
    });
  }

  next();
};

module.exports = {
  generalLimiter,
  authLimiter,
  sensitiveLimiter,
  sanitizeRequest,
  securityHeaders,
  validateRequestSize,
  blockSuspiciousPatterns
};

// Secure Express application with comprehensive error handling and input validation
const express = require('express');
const helmet = require('helmet');
const { validationResult, query } = require('express-validator');

const securityConfig = require('./config/security');
const { errorHandler, NotFoundError } = require('./utils/errors');
