const {
  generalLimiter,
  authLimiter,
  securityHeaders,
  validateRequestSize,
  blockSuspiciousPatterns
} = require('./middleware/security');

const app = express();

// Trust proxy settings (configure based on your deployment environment)
app.set('trust proxy', 1);

// Security middleware - Helmet sets various HTTP headers for security
app.use(helmet(securityConfig.helmetConfig));

// Additional security headers
app.use(securityHeaders);

// Request size validation (early in the chain)
app.use(validateRequestSize);

// Rate limiting to prevent brute-force and DoS attacks
app.use(generalLimiter);

// Body parsing with size limits to prevent payload attacks
app.use(express.json({ 
  limit: securityConfig.bodyParser.jsonLimit,
  strict: true // Only accept arrays and objects
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: securityConfig.bodyParser.urlencodedLimit,
  parameterLimit: securityConfig.bodyParser.parameterLimit
}));

// Input sanitization
app.use(sanitizeInput);

// Block suspicious patterns (SQL injection, XSS, etc.)
app.use(blockSuspiciousPatterns);

// ========== ROUTES ==========

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: Math.floor(process.uptime()),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users list endpoint with pagination and validation
