const request = require('supertest');
const app = require('../app');

describe('Security Tests', () => {
  describe('Security Headers', () => {
    it('should include security headers via Helmet', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['x-content-type-options']).toBe('nosniff');
      expect(res.headers['x-frame-options']).toBeDefined();
      expect(res.headers['x-dns-prefetch-control']).toBeDefined();
    });
  });

  describe('Rate Limiting', () => {
    it('should handle rate limiting headers', async () => {
      const res = await request(app).get('/health');

      // Rate limit headers should be present
      expect(res.headers['ratelimit-limit']).toBeDefined();
      expect(res.headers['ratelimit-remaining']).toBeDefined();
    });
  });

  describe('Input Validation', () => {
    it('should return 404 for undefined routes', async () => {
      const res = await request(app).get('/undefined-route');

      expect(res.status).toBe(404);
      expect(res.body.error).toBe('Not Found');
    });

    it('should handle invalid user IDs', async () => {
      const res = await request(app).get('/users/invalid');

      expect(res.status).toBe(400);
      expect(res.body.error).toBe('Invalid user ID');
    });
  });

  describe('Data Exposure', () => {
    it('should not expose email addresses in users list', async () => {
      const res = await request(app).get('/users');

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);

      // Check that emails are not exposed
      res.body.forEach(user => {
        expect(user.email).toBeUndefined();
        expect(user.id).toBeDefined();
        expect(user.name).toBeDefined();
      });
    });

    it('should limit health endpoint info in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const res = await request(app).get('/health');

      expect(res.status).toBe(200);
      expect(res.body.status).toBe('ok');
      // Should not include timestamp in production
      expect(res.body.timestamp).toBeUndefined();

      process.env.NODE_ENV = originalEnv;
    });
  });

  describe('CORS', () => {
    it('should handle CORS preflight', async () => {
      const res = await request(app)
        .options('/health')
        .set('Origin', 'http://localhost:3000');

      expect(res.headers['access-control-allow-origin']).toBeDefined();
    });
  });

  describe('Error Handling', () => {
    it('should not expose stack traces in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      // Trigger an error by making a request that causes issues
      // This is a simplified test - in reality you'd test actual error scenarios
