  param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  handleValidationErrors,
  (req, res, next) => {
    try {
      const id = parseInt(req.params.id);
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === id);

      if (!user) {
        const error = new Error('User not found');
        error.statusCode = 404;
        throw error;
      }

      res.json(user);
    } catch (error) {
      next(error);
    }
  }
);

// Create user endpoint with strict validation
app.post('/users',
  strictLimiter,
  [
    body('name').trim().notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters')
      .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters')
      .escape(),
    body('email').isEmail().withMessage('Valid email is required')
      .normalizeEmail()
      .isLength({ max: 255 }).withMessage('Email too long'),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // In production, this would check database for duplicates
      const newUser = {
        id: Date.now(), // Use proper UUID in production
        name,
        email,
        createdAt: new Date().toISOString()
      };

      // Don't log sensitive data
      console.log('User created:', { id: newUser.id, createdAt: newUser.createdAt });

      res.status(201).json(newUser);
    } catch (error) {
      next(error);
    }
  }
);

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler (must be last)
app.use(errorHandler);

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000 in', process.env.NODE_ENV || 'development', 'mode');
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
    process.exit(0);
  });
});

module.exports = app;

