### 2. **No Security Headers**
- Missing essential security headers
- **Recommendation**: Use `helmet` middleware

```javascript
const helmet = require('helmet');
app.use(helmet());
```

Helmet adds:
- Content Security Policy (CSP)
- X-DNS-Prefetch-Control
- X-Frame-Options
- X-Powered-By removal
- X-Content-Type-Options
- And more...

### 3. **No Rate Limiting**
- API endpoints are unprotected against abuse
- **Recommendation**: Add `express-rate-limit`

```javascript
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});

app.use('/api/', apiLimiter);
```

### 4. **No CORS Configuration**
- CORS is not configured, which could lead to security issues
- **Recommendation**: Configure CORS explicitly

```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

### 5. **No Error Handling**
- No centralized error handling middleware
- Stack traces may leak in production
- **Recommendation**: Add error handling middleware

```javascript
// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(err.status || 500).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});
```

